export type ConsultationReportReference = {
  tenantSlug: string;
  assessmentSessionId: string;
  reportTemplateVersionId: string;
  projectQuestionnaireId: string | null;
  questionnaireVersionId: string | null;
};

export function readConsultationReportReference(
  orderMetadata: unknown,
): ConsultationReportReference | null {
  const metadata = asRecord(orderMetadata);
  const tenantSlug = optionalString(metadata, "tenantSlug");
  const assessmentSessionId = optionalString(
    metadata,
    "assessmentSessionId",
  );
  const reportTemplateVersionId = optionalString(
    metadata,
    "reportTemplateVersionId",
  );

  if (!tenantSlug || !assessmentSessionId || !reportTemplateVersionId) {
    return null;
  }

  return {
    tenantSlug,
    assessmentSessionId,
    reportTemplateVersionId,
    projectQuestionnaireId: optionalString(
      metadata,
      "projectQuestionnaireId",
    ),
    questionnaireVersionId: optionalString(
      metadata,
      "questionnaireVersionId",
    ),
  };
}

