export function buildMyConsultationReportHref(
  orderMetadata: unknown,
): string | null {
  const reference = readConsultationReportReference(orderMetadata);
  if (!reference) return null;

  return appendScope(
    `/my/assessment/sessions/${reference.assessmentSessionId}` +
      `/report/${reference.reportTemplateVersionId}`,
    reference,
  );
}

export function buildAdminConsultationReportHref(
  orderMetadata: unknown,
): string | null {
  const reference = readConsultationReportReference(orderMetadata);
  if (!reference) return null;

  return appendScope(
    `/t/${encodeURIComponent(reference.tenantSlug)}` +
      `/assessment-sessions/${reference.assessmentSessionId}` +
      `/report/${reference.reportTemplateVersionId}`,
    reference,
  );
}
